function OverseaManageCustomerItemSubmissionPopup:InitShowData(ids)
    self.goods = {}
    local ids = string.split(ids,';')
    if table.count(ids) > 0  then
        for i, v in pairs(ids) do
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting6073,"MaidCoffeeGuestQuestRandomGoodsVo",v)
            if not isNull(vo) then
                for k, j in pairs(vo.itemId) do
                    table.insert(self.goods,{groupId = v,goodsId = tonumber(j)})
                end
            end
        end
    end
end

