            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

function OverseaManageCustomerItemSubmissionPopup:RefreshShow()
    self.count = table.count(self.goods)
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(self.count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, self.count)
        self.ScrollView.ContainerTrans.anchoredPosition3D = Vector3(0,0,0)
        self.ScrollView:VaildAndSetContainerPos()
    end
end

function OverseaManageCustomerItemSubmissionPopup:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if self.count < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem(GoodsCell)
    if not isNull(cell) then
        local goodsNode = cell.transform:Find("GoodNode")
        if not isNull(goodsNode) then
            local env = CfUtils.GetLuaScr(goodsNode,"Game.Behaviours.GoodNodeMB")
            local goodsId = self.goods[index + 1].goodsId
            env:Reload({goodsId = goodsId, isShowNo = true,text = self:GetTextShow(goodsId)})
            local haveNum = GoodsUtils.GetThingNo(goodsId)
            local isEnough = haveNum >= checkNumber(self.parameters.needNum)
            env:SetEnoughState(not (isEnough))
            env:SetClickButtonAction(function(goodsId, id)
                if haveNum > 0 then
                    if not isNull(self.curIndex) and self.curIndex == index + 1 then
                        return
                    end
                    local lastIndex = self.curIndex
                    self:DoSelect(lastIndex)
                    self.curIndex = index + 1
                    env:SetCheckState(true)
                else
                    ----点击出tip
                    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                    if isTable(vo) then
                        --GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, vo.desc, vo.quality, vo.id)
                        GameUtils.ShowCommonGoodsTipsBoard(goodsNode.gameObject, vo.id, true)
                    end
                end
            end)
        end
    end
    return cell
end

function OverseaManageCustomerItemSubmissionPopup:DoSelect(lastIndex)
    if not isNull(lastIndex) then
        local cellItem = self.ScrollView:GetShownItemByItemIndex(lastIndex - 1)
        if cellItem then
            local goodsNode = cellItem.transform:Find("GoodNode")
            if not isNull(goodsNode) then
                local env = CfUtils.GetLuaScr(goodsNode,"Game.Behaviours.GoodNodeMB")
                env:SetCheckState(false)
            end
        end
    end
end

function OverseaManageCustomerItemSubmissionPopup:GetTextShow(goodsId)
    return string.format("x%s",GoodsUtils.GetThingNo(goodsId))
end

return OverseaManageCustomerItemSubmissionPopup